class Solution {
    private int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
    public List<String> findWords(char[][] board, String[] words) {
        int[][] trie = new int[words.length * 11 + 1][26];
        String[] endWord = new String[trie.length];
        int size = 1;
        for (String w : words) {
            int node = 0;
            for (char c : w.toCharArray()) {
                int idx = c - 'a';
                if (trie[node][idx] == 0) trie[node][idx] = size++;
                node = trie[node][idx];
            }
            endWord[node] = w;
        }
        List<String> result = new java.util.ArrayList<>();
        int m = board.length, n = board[0].length;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                dfs(board, i, j, 0, trie, endWord, result);
        return result;
    }
    private void dfs(char[][] board, int r, int c, int node, int[][] trie, String[] endWord, List<String> result) {
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length || board[r][c] == '#') return;
        int idx = board[r][c] - 'a';
        if (trie[node][idx] == 0) return;
        node = trie[node][idx];
        if (endWord[node] != null) { result.add(endWord[node]); endWord[node] = null; }
        char tmp = board[r][c];
        board[r][c] = '#';
        for (int[] d : dirs) dfs(board, r + d[0], c + d[1], node, trie, endWord, result);
        board[r][c] = tmp;
    }
}
